    }

    test_fixture(
        if input.to_string_lossy().ends_with(".ts") {
            syntax_default_ts()
        } else {
            syntax_default()
        },
        &|t| create_pass(t.comments.clone(), &input),
        &input,
        &output,
        FixtureTestConfig {
            allow_error: true,
            module: Some(true),
            ..Default::default()
        },
    );
