    ///
    /// When a decorated subclass extends a base class, its static members are
    /// relocated onto the generated wrapper class (which extends the decorator
    /// `_identity` helper, not the original base). As a result a plain `super`
    /// reference would no longer resolve to the base class. This rewrites such
    /// references to explicit prototype-chain lookups against `class_name`
    /// (e.g. `_get(_get_prototype_of(_Derived), "prop", this)`), which keeps
    /// them pointing at the real base class at runtime.
    fn rewrite_super_in_moved_static<N>(&self, node: &mut N, class_name: &Ident)
    where
